import {readFile,mkdir,writeFile} from 'node:fs/promises';
import path from 'node:path';
import {createHash} from 'node:crypto';
import {ProgramBuilder,variable,instruction,imagePut,expr as E,assignExpression,assignProfile,templatePage} from 'galbox-sdk/port-kit';
import {parseProgram,string,f64,i64,list,dict,i32,nullValue} from 'galbox-sdk/protocol';
import {createReleaseManifest,inspectResource} from 'galbox-sdk/release';
const root='tests/player-app/public/data';await mkdir(root,{recursive:true});const original=parseProgram(JSON.parse(await readFile('tests/fixtures/game-data/standard-novel/program.json','utf8'))),image=original.assets.find(a=>a.id==='shore'),music=original.assets.find(a=>a.id==='bgm');if(!image||!music)throw new Error('Original assets');
const b=new ProgramBuilder({gameId:'lighthouse-supplies',title:'灯塔来信 · 补给簿',release:'supplies-1',entry:'main'}),background=b.asset('image',{...image,path:'../'+image.path}),bgm=b.asset('audio',{...music,path:'../'+music.path}),balance=variable('balance','f64'),shipment=variable('shipment','i64'),items=variable('items','list'),ledger=variable('ledger','dict'),route=variable('route','string');
b.global({...balance,initial:f64(12.5)}).global({...shipment,initial:i64('9007199254740993')}).global({...items,initial:list([string('灯油'),string('信纸')])}).global({...ledger,initial:dict([{key:'灯油',value:i32(2)},{key:'信纸',value:nullValue()}])}).global({...route,initial:string('')});
b.function({id:'main',entry:'supplies:stage',layout:1,params:[],locals:[],returns:'void',code:[
 imagePut('supplies:stage','background',background,{x:0,y:0,alpha:1}),instruction('audio.play',{at:'supplies:music',task:'music',asset:bgm.id,channel:'bgm',gain:.2,loop:true,restore:'replay'}),
 templatePage('supplies:before','supplies.before','zh-1',E.text('补给簿'),E.template`余额：${E.variable(balance)}。货号：${E.variable(shipment)}。\n柜里有${E.listLength(E.variable(items))}种物资：${E.listAt('string',E.variable(items),E.integer(0))}和${E.listAt('string',E.variable(items),E.integer(1))}。\n信纸栏：${E.choose(E.equal(E.dictGet('null',E.variable(ledger),E.text('信纸')),E.nil()),E.text('待登记'),E.text('已有记录'))}。澪说，今天要多准备几份回信。`),
 assignExpression('supplies:pay',balance,E.f64Binary('sub',E.variable(balance),E.f64Binary('mul',E.real(.75),E.real(3)))),assignExpression('supplies:ship',shipment,E.i64Binary('add',E.variable(shipment),E.wide(1n))),assignExpression('supplies:items',items,E.listPush(E.variable(items),E.text('回信'))),assignExpression('supplies:paper',ledger,E.dictSet(E.variable(ledger),E.text('信纸'),E.integer(3))),assignExpression('supplies:ledger',ledger,E.dictSet(E.variable(ledger),E.text('余额'),E.variable(balance))),assignProfile('supplies:persist','supplyLog',E.variable(ledger)),
 templatePage('supplies:after','supplies.after','zh-1',E.text('澪'),E.template`三份信纸共花了2.25，余额还有${E.variable(balance)}。\n新货号是${E.variable(shipment)}。柜里已有${E.listLength(E.variable(items))}种物资，信纸登记了${E.dictGet('i32',E.variable(ledger),E.text('信纸'))}份。\n「最后一份，要寄给谁呢？」`),
 instruction('choice',{at:'supplies:choice',dest:'route',options:[{id:'send',text:'给海上的人寄去回信',target:'supplies:pack'},{id:'keep',text:'为下一位守灯人留一份',target:'supplies:pack'}]}),
 assignExpression('supplies:pack',items,E.listPush(E.variable(items),E.choose(E.equal(E.variable(route),E.text('send')),E.text('寄出的包裹'),E.text('留灯的备用物资')))),
 templatePage('supplies:ending','supplies.ending','zh-1',E.text('灯塔来信'),E.template`${E.listAt('string',E.variable(items),E.binary('sub',E.listLength(E.variable(items)),E.integer(1)))}，已经安放妥当。\n账目留在补给簿上，海风会替我们记住回信的方向。`),instruction('profile.set',{at:'supplies:unlock',key:'suppliesComplete',value:{kind:'bool',value:true}}),instruction('control.end',{at:'supplies:end'})]});
const program=b.build(),resources=await Promise.all(program.assets.map(async a=>inspectResource(a,new Uint8Array(await readFile(path.resolve(root,a.path))),bytes=>new TextDecoder('utf-8',{fatal:true}).decode(bytes))));const release=await createReleaseManifest({program,series:'1',resources},{async sha256(text){return createHash('sha256').update(text,'utf8').digest('hex');}});
for(const target of [root,'tests/fixtures/game-data/data-novel']){await mkdir(target,{recursive:true});await writeFile(`${target}/program.json`,JSON.stringify(program,null,2)+'\n');await writeFile(`${target}/program.json.release.json`,JSON.stringify(release,null,2)+'\n');}console.log('Built original supply logbook with f64/i64/ordered collections and profile expressions');
